//Script para Internacion
const ordenesLimpias = $input.all().map((item) => {
  const data = item.json;

  // desestructuracion de datos para mejor orden
  const paciente = data.patient_data || {};
  const orden = data.clinical_order || {};

  const nombre = paciente.first_name || "";
  const apellido = paciente.last_name || "";

  // pseudonimo de telegram
  const iniciales = `${nombre.charAt(0) || "X"}.${apellido.charAt(0) || "X"}.`;

  // formateo fecha nacimiento
  const bd = paciente.birth_date || {};
  const fechaNac = bd.year ? `${bd.year}-${bd.month}-${bd.day}` : "";

  // calculo de edad
  const dob = new Date(fechaNac);
  const hoy = new Date();
  let edad = hoy.getFullYear() - dob.getFullYear();
  const m = hoy.getMonth() - dob.getMonth();

  if (m < 0 || (m === 0 && hoy.getDate() < dob.getDate())) {
    edad--;
  }

  // urgencia como booleano, ya viene en ese formato
  const prioridad = data.is_urgent;

  // ubicacion mapeada en un solo campo
  const ubicacion = `${orden.sector || "S/D"} - Hab: ${orden.room || "-"} Cama: ${orden.bed || "-"}`;

  // retorno del objeto limpio
  return {
    external_id: `I-${data.request_id}`,
    origin: "INTERNACION",
    modality: orden.modality,
    medical_order: orden.procedure,
    diagnosis: orden.diagnosis,
    observations: orden.observations || "Sin observaciones",
    location: ubicacion,
    study_setting: orden.study_setting || "Rayos",
    patient_name: nombre,
    patient_lastname: apellido,
    patient_pseudonym: iniciales,
    patient_dni: paciente.national_id,
    patient_dob: fechaNac,
    patient_age: edad, 
    requesting_physician: data.clinical_order.requesting_physician || "No especificado",
    is_urgent: prioridad,
    is_active: true,
  };
});

// Retornamos la estructura que n8n necesita para seguir el flujo
return ordenesLimpias.map((orden) => ({ json: orden }));

// Script para Guardia
const ordenesLimpias = $input.all().map((item) => {
  const data = item.json;

  // formateo de nombre
  const partesNombre = (data.nom_paciente || "").split(", ");
  const apellido = partesNombre[0] || "";
  const nombre = partesNombre[1] || "";

  // pseudonimo para telegram
  const iniciales = `${nombre.charAt(0) || "X"}.${apellido.charAt(0) || "X"}.`;

  // urgencia
  const prioridad = data.urgente === "SI";

  const prestacion = data.estudio_req || "Sin detalle";

  let modalidadInferida = "DX";
  if (prestacion.includes("resonancia") || prestacion.includes("RM"))
    modalidadInferida = "MR";
  else if (prestacion.includes("ecograf") || prestacion.includes("ecografía"))
    modalidadInferida = "US";
  else if (
    prestacion.includes("tomograf") ||
    prestacion.includes("TC") ||
    prestacion.includes("TAC")
  )
    modalidadInferida = "CT";
  else if (prestacion.includes("radiograf") || prestacion.includes("rx"))
    modalidadInferida = "DX";

  // calculo de edad
  const dob = new Date(data.fecha_nacimiento);
  const hoy = new Date();
  let edad = hoy.getFullYear() - dob.getFullYear();
  const m = hoy.getMonth() - dob.getMonth();
  if (m < 0 || (m === 0 && hoy.getDate() < dob.getDate())) {
    edad--;
  }
  // retorno de objeto formateado
  return {
    external_id: `G-${data.id_transaccion}`,
    origin: "GUARDIA",
    modality: modalidadInferida,
    medical_order: prestacion,
    diagnosis: data.diagnostico || "Sin diagnostico",
    observations: data.observaciones || "Sin observaciones",
    location: data.ubicacion_actual || "Sin ubicacion",
    study_setting: data.lugar_estudio || "Rayos", 
    patient_name: nombre,
    patient_lastname: apellido,
    patient_pseudonym: iniciales,
    patient_dni: data.doc_identidad || "Sin DNI",
    patient_dob: data.fecha_nacimiento || "Sin fecha de nacimiento",
    patient_age: edad,
    requesting_physician: data.solicitante || "Solicitante no especificado",
    is_urgent: prioridad,
    is_active: true,
  };
});

// Retornamos la estructura que n8n necesita para seguir el flujo
return ordenesLimpias.map((orden) => ({ json: orden }));

// Script para Ambulatorio CORREGIDO
const ordenesLimpias = $input.all().map((item) => {
  const data = item.json;

  const partesNombre = (data.PACIENTE_DATA || "").split("^");
  const apellido = partesNombre[0] || "";
  const nombre = partesNombre[1] || "";
  const iniciales = `${nombre.charAt(0) || "X"}.${apellido.charAt(0) || "X"}.`;

  let modalidadInferida = "DX";
  const prestacion = (data.PRESTACION_DESC || "").toLowerCase();
  if (prestacion.includes("resonancia") || prestacion.includes("RM")) modalidadInferida = "MR";
  else if (prestacion.includes("ecograf") || prestacion.includes("ecografía")) modalidadInferida = "US";
  else if (prestacion.includes("tomograf") || prestacion.includes("TC") || prestacion.includes("TAC")) modalidadInferida = "CT";

  // --- CORRECCIÓN DE FECHA Y EDAD ---
  // El mock viene YYYY-MM-DD (ej: 1983-12-15)
  const [anio, mes, dia] = data.FECHA_NACIMIENTO.split("-");

  // Creamos el objeto fecha (Ojo: en JS los meses van de 0 a 11, por eso mes - 1)
  const dob = new Date(`${anio}-${mes}-${dia}`);
  const hoy = new Date();

  let edad = hoy.getFullYear() - dob.getFullYear();
  const m = hoy.getMonth() - dob.getMonth();
  if (m < 0 || (m === 0 && hoy.getDate() < dob.getDate())) {
    edad--;
  }

  const edadFinal = isNaN(edad) ? 0 : edad;

  return {
    external_id: `A-${data.ID_CITA}`,
    origin: "AMBULATORIO",
    modality: modalidadInferida,
    medical_order: data.PRESTACION_DESC,
    diagnosis: data.DIAGNOSTICO || "Sin especificar",
    observations: data.OBSERVACIONES || "Sin observaciones",
    location: "Atención Ambulatoria",
    study_setting: "Rayos",
    patient_name: nombre,
    patient_lastname: apellido,
    patient_pseudonym: iniciales,
    patient_dni: String(data.NRO_DOCUMENTO),
    patient_dob: data.FECHA_NACIMIENTO,
    patient_age: edadFinal, 
    requesting_physician: data.MEDICO_DERIVANTE || "No especificado",
    is_urgent: false,
    is_active: true,
  };
});

return ordenesLimpias.map((orden) => ({ json: orden }));
